function money(n){return `MOP ${n.toLocaleString('en-US')}`}
function normalizePhone(value){return value.replace(/\D/g,'')}
function normalizeInstagram(value){return value.trim().replace(/^@+/,'')}
function validPersonName(value){const name=value.trim();return name.length>=2&&/\p{L}/u.test(name)}
function validInstagram(value){const username=normalizeInstagram(value);return /^(?!.*\.\.)[A-Za-z0-9._]{1,30}$/.test(username)&&!username.includes('instagram.com')}
function readCheckoutDraft(){try{return JSON.parse(localStorage.getItem(checkoutDraftKey)||'null')||{}}catch(error){localStorage.removeItem(checkoutDraftKey);return {}}}
function discountActive(){const today=new Date().toISOString().slice(0,10);return discountSettings.enabled&&today>=discountSettings.start&&today<=discountSettings.end}
function productPrice(p){return discountActive()&&p.id===discountSettings.productId?Number(discountSettings.salePrice):p.price}
function startAnnouncementCarousel(){clearInterval(announcementTimer);const node=$('#announcementText'),items=announcements.filter(Boolean);if(!node||!items.length)return;let index=0;const show=()=>{node.classList.add('changing');setTimeout(()=>{node.textContent=items[index];node.classList.remove('changing');index=(index+1)%items.length},180)};node.textContent=items[0];index=items.length>1?1:0;if(items.length>1)announcementTimer=setInterval(show,4000)}
const demoProductImages=['assets/musis-hero.png','assets/musis-hero-2.jpg','assets/musis-hero-3.jpg'];
function productImage(p,variant=0){const index=Math.max(0,products.findIndex(item=>item.id===p.id));return demoProductImages[(index+variant)%demoProductImages.length]}
function productImageMarkup(p,variant=0,alt='',eager=false){return `<img class="product-image" src="${productImage(p,variant)}" data-fallback="${demoProductImages[0]}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'}>`}
function bindProductImages(root=document){root.querySelectorAll('.image-loading').forEach(shell=>{const img=shell.querySelector('.product-image');if(!img||img.dataset.bound)return;img.dataset.bound='true';const loaded=()=>{shell.classList.remove('image-error');shell.classList.add('image-loaded')};const failed=()=>{const fallback=img.dataset.fallback;if(fallback&&!img.src.endsWith(fallback)){img.src=fallback;return}shell.classList.remove('image-loaded');shell.classList.add('image-error');img.remove()};img.addEventListener('load',loaded);img.addEventListener('error',failed);if(img.complete)(img.naturalWidth?loaded():failed())})}
function purchaseLimit(p){return p.preorder?5:Math.max(0,Number(p.stock)||0)}
function cartQuantity(id){return cart.filter(item=>item.id===id).reduce((sum,item)=>sum+item.qty,0)}
function normalizeCart(items){const totals={};return items.reduce((result,item)=>{const p=products.find(product=>product.id===item.id);if(!p||(p.cat==='rings'&&!item.size))return result;const remaining=purchaseLimit(p)-(totals[p.id]||0),qty=Math.min(Math.max(1,Math.floor(Number(item.qty)||1)),remaining);if(qty<1)return result;totals[p.id]=(totals[p.id]||0)+qty;result.push({...item,qty});return result},[])}
const instagramProfile='https://www.instagram.com/musis.studio/';
function fallbackCopyText(text){const field=document.createElement('textarea');field.value=text;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();let copied=false;try{copied=document.execCommand('copy')}catch(error){copied=false}field.remove();return copied}
async function copyText(text){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);return true}catch(error){return fallbackCopyText(text)}}return fallbackCopyText(text)}
function showRestockDialog(message,copied){$('#restockMessage').value=message;$('#restockCopyStatus').textContent=copied?'訊息已複製，前往 Instagram 後直接貼上即可。':'瀏覽器未能自動複製，請按「重新複製」或手動選取訊息。';const dialog=$('#restockDialog');if(!dialog.open)dialog.showModal()}
function openRestockInquiry(p,size=''){if(p.cat==='rings'&&!size){toast('請先選擇希望補貨的戒指尺寸');return false}const message=`你好，我想查詢 ${p.id}「${p.name}」${size?`（尺寸：${size}）`:''}的預購安排。`;copyText(message).then(copied=>showRestockDialog(message,copied));return true}
function heartSvg(saved=false){return `<svg class="heart-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21.2 3.5 12.5C.8 9.7 1.3 5.3 4.4 3.2c2.5-1.7 5.8-1.1 7.6 1.3 1.8-2.4 5.1-3 7.6-1.3 3.1 2.1 3.6 6.5.9 9.3L12 21.2Z"${saved?' fill="currentColor"':''}/></svg>`}
function productCard(p){const saved=favorites.includes(p.id),sale=productPrice(p)<p.price,soldOut=!p.preorder&&purchaseLimit(p)===0,badge=soldOut?'<span class="badge sold-out-badge">SOLD OUT</span>':p.preorder?'<span class="badge">PRE-ORDER</span>':sale?'<span class="badge sale-badge">SALE</span>':p.stock<=2?'<span class="badge">LOW STOCK</span>':'';return `<article class="product-card" data-id="${p.id}"><div class="product-visual image-loading">${productImageMarkup(p,0,p.name)}${badge}<button class="favorite-button ${saved?'saved':''}" data-favorite="${p.id}" aria-label="${saved?'取消收藏':'收藏'} ${p.name}">${heartSvg(saved)}</button><button class="quick-add ${soldOut?'restock-notice':''}" aria-label="${soldOut?'透過 Instagram 詢問補貨':p.cat==='rings'?'選擇尺寸':'加入'} ${p.name}">${soldOut?'IG 詢問補貨':'＋'}</button></div><div class="product-info"><small>${p.id} · 925 SILVER</small><h3>${p.name}</h3><p class="product-price">${sale?`<del>${money(p.price)}</del><strong>${money(productPrice(p))}</strong>`:money(p.price)}</p></div></article>`}
function bindProductCards(){bindProductImages();$$('.product-card').forEach(card=>{card.querySelector('.quick-add').onclick=e=>{e.stopPropagation();const p=products.find(item=>item.id===card.dataset.id);if(!p)return;if(!p.preorder&&purchaseLimit(p)===0){if(p.cat==='rings'){location.hash=`product?id=${p.id}`;toast('請先選擇希望補貨的戒指尺寸');return}openRestockInquiry(p);return}if(p.cat==='rings'){location.hash=`product?id=${p.id}`;toast('請先選擇戒指尺寸');return}addToCart(p.id)};card.querySelector('.favorite-button').onclick=e=>{e.stopPropagation();toggleFavorite(card.dataset.id,e.currentTarget)};card.onclick=()=>location.hash=`product?id=${card.dataset.id}`})}
const PAGE_SIZE=12;
function renderPagination(container,totalPages,currentPage,onChange){if(!container)return;if(totalPages<=1){container.innerHTML='';return}container.innerHTML=`<button ${currentPage===1?'disabled':''} data-page="${currentPage-1}">← 上一頁</button>${Array.from({length:totalPages},(_,i)=>`<button class="${i+1===currentPage?'active':''}" data-page="${i+1}">${i+1}</button>`).join('')}<button ${currentPage===totalPages?'disabled':''} data-page="${currentPage+1}">下一頁 →</button>`;container.querySelectorAll('[data-page]:not([disabled])').forEach(button=>button.onclick=()=>onChange(Number(button.dataset.page)))}
function productSizes(p){return p.cat==='rings'&&Array.isArray(ringSizeSettings[p.id])&&ringSizeSettings[p.id].length?ringSizeSettings[p.id]:p.cat==='rings'?['均碼・開口戒']:[]}
function addToCart(id,size='',quantity=1){const p=products.find(x=>x.id===id);if(!p)return false;if(!p.preorder&&purchaseLimit(p)===0){toast('此商品目前售罄，請使用 Instagram 詢問補貨');return false}if(p.cat==='rings'&&!size){toast('請先選擇戒指尺寸');return false}const limit=purchaseLimit(p),current=cartQuantity(id),amount=Math.max(1,Math.floor(Number(quantity)||1));if(current+amount>limit){toast(p.preorder?'預訂商品每筆訂單最多 5 件':`現貨只剩 ${limit} 件`);return false}const row=cart.find(x=>x.id===id&&(x.size||'')===size);row?row.qty+=amount:cart.push({id,qty:amount,...(size?{size}:{})});saveCart();toast(`已加入 ${amount} 件商品${size?` · ${size}`:''}`);openCart();return true}
function saveFavorites(){localStorage.setItem('musis-favorites',JSON.stringify(favorites));const count=$('#favoritesCount');if(count)count.textContent=favorites.length}
function toggleFavorite(id,button){const saved=favorites.includes(id);favorites=saved?favorites.filter(x=>x!==id):[...favorites,id];saveFavorites();if(button){const active=!saved;button.classList.toggle('saved',active);button.innerHTML=button.classList.contains('detail-favorite')?`${heartSvg(active)}<span>${active?'已收藏':'收藏'}</span>`:heartSvg(active);button.setAttribute('aria-label',active?'取消收藏':'收藏')}toast(saved?'已取消收藏':'已加入收藏')}
function saveCart(){localStorage.setItem('musis-cart',JSON.stringify(cart));$('#cartCount').textContent=cart.reduce((n,x)=>n+x.qty,0);renderCart();if(checkoutCartSync&&$('#checkoutForm'))checkoutCartSync()}
function cartSubtotal(){return cart.reduce((n,x)=>{const p=products.find(v=>v.id===x.id);return n+(p?productPrice(p):0)*x.qty},0)}
function renderCart(){const box=$('#cartItems');if(!box)return;const hasPreorder=cart.some(item=>products.find(p=>p.id===item.id)?.preorder),notice=hasPreorder?'<p class="preorder-order-note">訂單包含預訂商品，預設待商品齊全後一併寄出。</p>':'';box.innerHTML=cart.length?notice+cart.map((x,index)=>{const p=products.find(v=>v.id===x.id),sale=productPrice(p)<p.price,atLimit=cartQuantity(p.id)>=purchaseLimit(p);return `<div class="cart-row"><div class="cart-thumb image-loading">${productImageMarkup(p,0,'')}</div><div><small>${p.id}${x.size?` · ${x.size}`:''}</small>${p.preorder?'<span class="order-item-status">預訂商品</span>':''}<h4>${p.name}</h4><b>${sale?`<del>${money(p.price)}</del> ${money(productPrice(p))}`:money(p.price)}</b><div class="qty"><button data-delta="-1" data-index="${index}" aria-label="減少 ${p.name} 數量">−</button><span>${x.qty}</span><button data-delta="1" data-index="${index}" ${atLimit?'disabled':''} aria-label="增加 ${p.name} 數量">＋</button></div><small class="cart-limit">${p.preorder?'每筆最多 5 件':`現貨上限 ${purchaseLimit(p)} 件`}</small></div><button class="remove" data-remove="${index}" aria-label="移除 ${p.name}">×</button></div>`}).join(''):'<div class="empty">購物清單還是空的<br><small>選一件會陪你很久的銀飾。</small></div>';bindProductImages(box);const sub=cartSubtotal();$('#cartSubtotal').textContent=money(sub);$('#shippingBar').style.width=`${Math.min(100,sub/300*100)}%`;$('#shippingMessage').textContent=sub>=300?'已享澳門免運':`再選購 ${money(300-sub)} 即享澳門免運`;box.querySelectorAll('[data-delta]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.index),row=cart[index],p=products.find(item=>item.id===row.id),delta=Number(b.dataset.delta);if(delta>0&&cartQuantity(p.id)>=purchaseLimit(p)){toast(p.preorder?'預訂商品每筆訂單最多 5 件':`現貨只剩 ${purchaseLimit(p)} 件`);return}row.qty+=delta;if(row.qty<1)cart.splice(index,1);saveCart()});box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);saveCart()})}
function openCart(){if(location.hash.startsWith('#admin'))return;$('#cartDrawer').classList.add('open');$('#cartDrawer').setAttribute('aria-hidden','false');$('#cartButton').setAttribute('aria-expanded','true');$('#scrim').classList.add('open')}
