function bindHeroCarousel(){const slides=$$('.hero-slide'),dots=$$('.hero-dots button');if(!slides.length)return;let active=0;const show=i=>{active=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===active));dots.forEach((d,n)=>d.classList.toggle('active',n===active))};const play=()=>{clearInterval(heroCarouselTimer);heroCarouselTimer=setInterval(()=>show(active+1),5200)};$('.hero-arrow.prev').onclick=()=>{show(active-1);play()};$('.hero-arrow.next').onclick=()=>{show(active+1);play()};dots.forEach((d,i)=>d.onclick=()=>{show(i);play()});$('.hero-image').onmouseenter=()=>clearInterval(heroCarouselTimer);$('.hero-image').onmouseleave=play;play()}
